// Suscriptor de prueba SOLO PARA STAGING, mientras no existan Ingesta RAG (HT-50) ni Service Desk (HT-41).
// Para simular un suscriptor caido: SUSCRIPTOR_CAIDO = true y enviar un evento con datos.simular_fallo = true.
// Para "corregirlo": cambiar SUSCRIPTOR_CAIDO a false y ejecutar el workflow de reproceso.
const SUSCRIPTOR_CAIDO = true;

const evento = $input.item.json;
if (SUSCRIPTOR_CAIDO && evento.datos && evento.datos.simular_fallo === true) {
  throw new Error('Suscriptor de prueba caido (datos.simular_fallo = true)');
}
return [{ json: { recibido: true, id: evento.id, tipo: evento.tipo } }];
